          id="fullname"
          name="fullName"
          type="text"
          required={true}
          value={formData.fullName}
          onChange={handleChange}
        />
        <FormField
          label="Email Address"
          id="email"
          name="email"
          type="email"
          required={true}
          value={formData.email}
          onChange={handleChange}
        />
        <FormField
          label="Phone Number"
          id="phone"
          name="phone"
          type="tel"
          required={false}
          helperText="Expected format: (123) 456-7890"
          value={formData.phone}
          onChange={handleChange}
        />
        <button type="submit">Submit</button>
      </form>
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<ContactForm />);
